    $svc=New-Object -ComObject 'Schedule.Service';$svc.Connect();$tasks=@($svc.GetFolder('\').GetTasks(1)|?{$_.Name-match'^SleepStagePaper-r14-(?:COM|Canary)-'});if($tasks.Count){throw 'r14 Scheduler namespace is not empty'}
}
Assert-NamespaceEmpty
$launchResolved=(Resolve-Path -LiteralPath $LaunchEvidencePath).Path;$launchSha=Get-Sha $launchResolved;if($launchSha-ne$ExpectedLaunchEvidenceSha256.ToLowerInvariant()){throw 'r14 launch evidence SHA mismatch'};$launch=Get-Content -LiteralPath $launchResolved -Raw|ConvertFrom-Json -ErrorAction Stop
$canonicalLaunch='E:\blp\sleep_stage_reproduction\runtime\driver-recovery\r14-scalar-action-launch-test-evidence-20260831-v2.json';if((Get-Sha $canonicalLaunch)-ne$launchSha-or-not[Linq.Enumerable]::SequenceEqual([IO.File]::ReadAllBytes($launchResolved),[IO.File]::ReadAllBytes($canonicalLaunch))){throw 'r14 launch evidence copies differ'}
