if($reviews[0].review_id-ne'authorization_contract_review'-or$reviews[0].status-ne'material_finding_closed'-or[string]::IsNullOrWhiteSpace([string]$reviews[0].agent_id)-or$reviews[0].finding_id-ne'R14-AUTH-PROVENANCE-001'-or$reviews[0].closure_status-ne'closed'){throw 'r14 initial review/finding closure failed'}
