    exactly_once=[ordered]@{dispatch_marker=(Join-Path $logRoot "$prefix.dispatch.lock");attempt_marker=(Join-Path $logRoot "$prefix.launch.lock");file_mode='CreateNew';file_share='None';no_retry_resume_reuse=$true;attempt_count=0;dispatch_marker_absent=$true;attempt_marker_absent=$true;child_run_directories_absent=$true}
    launch_test_evidence=[ordered]@{status='pass';schema_version=2;pilot_launched=$false;validated_by_windows_powershell_5_1=$true;local_path=$launchResolved;canonical_path=$canonicalLaunch;sha256=$launchSha;source_bindings=@($launch.source_bindings).Count;canary_case_id=[string]$launch.registered_production_shape_canary.case_id}
